-- =====================================================================
-- Sistema de Inspección de Edificaciones Post-Sismo
-- DATOS INICIALES + CARGA DE INSPECCIONES
-- =====================================================================
-- Cargar DESPUÉS de schema.sql:
--   mysql -u root -p < database/schema.sql
--   mysql -u root -p < database/datos_iniciales.sql
--
-- Contiene:
--   1) Datos base del sistema: roles, módulos, permisos (RBAC) y los 3
--      usuarios por defecto.
--        - admin      / Admin#2026       (Administrador, acceso NACIONAL)
--        - inspector  / Inspector#2026    (Inspector)
--        - supervisor / Supervisor#2026   (Supervisor)
--      >> Cambie estas contraseñas antes de producción. <<
--   2) Las 510 inspecciones existentes ya migradas al esquema nacional.
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
USE `inspecciones_sismos`;

-- ---------------------------------------------------------------------
-- 1) DATOS BASE (roles, módulos, permisos, usuarios)
-- ---------------------------------------------------------------------

